// 韩国小知识（자료실）— 结构化科普文章，阅览室第 3 个子入口。
// 内容形态：中文科普为主 + 穿插韩语词卡。与 reading-new.ts（逐句韩语精读）分家，schema 独立。
// 正文 blocks[] 由旧 korea-articles HTML 结构化迁移而来，ko/ro/scene/zh 逐字保留。

export type KBBlock =
  | { type: 'intro'; text: string }
  | { type: 'toriQuote'; label?: string; text: string }
  | { type: 'sectionBreak' }
  | { type: 'sectionTitle'; emoji: string; title: string; sub?: string }
  | { type: 'paragraph'; heading?: string; text: string }
  | { type: 'highlight'; variant: 'tip' | 'warning'; title?: string; text: string }
  | {
      type: 'cardGrid';
      variant: 'brand' | 'coffee' | 'place' | 'snack' | 'generic';
      cards: {
        emoji?: string;
        ko?: string;
        ro?: string;
        zh?: string;
        desc?: string;
        tip?: string;
        price?: string;
        tags?: string[];
      }[];
    }
  | {
      type: 'featureCard';
      emoji?: string;
      title: string;
      desc?: string;
      scenes?: { speaker?: string; ko: string; ro?: string; zh: string }[];
    }
  | { type: 'table'; head: string[]; rows: string[][] }
  | { type: 'steps'; steps: { label: string; desc?: string; ko?: string; ro?: string; zh?: string }[] }
  | { type: 'dialog'; lines: { speaker: string; ko: string; ro?: string; zh: string }[] }
  | { type: 'timeline'; items: { emoji?: string; label: string; desc: string }[] }
  | { type: 'compareVs'; left: { title: string; items: string[] }; right: { title: string; items: string[] } }
  | { type: 'trivia'; items: { tag: string; q: string; a: string }[] }
  // ★ 学习闭环：可加入生词本（点韩语发音 + 加词）
  | { type: 'phraseList'; title?: string; sub?: string; items: { ko: string; ro?: string; scene?: string; zh: string }[] }
  | { type: 'vocabList'; title?: string; items: { ko: string; ro?: string; zh: string }[] }
  | { type: 'ending'; text: string; next?: { slug: string; title: string } };

export interface KnowledgeArticle {
  slug: string;
  category: 'culture' | 'food' | 'travel';
  title: string;
  subtitle: string; // 韩语见出し（破折号前）+ 说明，沿用旧 subtitle
  emoji: string;
  readMinutes: number;
  bannerImage: string;
  blocks: KBBlock[];
}

