      text: '토리在首尔的时候做了一件事：从住的地方出门，走100步，数咖啡厅。结果数到了 4家。这不是特别繁华的街道，就是普通的住宅区。韩国人均咖啡消耗量是世界第一，首尔的咖啡厅密度更是让每一个第一次来的人目瞪口呆。但咖啡厅在韩国不只是"喝咖啡的地方"，它是办公室、是约会场所、是独处的避难所、是拍照的舞台……今天토리 带你彻底搞懂首尔的咖啡文化 ☕',
