      desc: `大酱汤 · 韩国家庭的味道（매일 먹는 국 / 每天都在喝）

된장（大豆酱）是韩国传统发酵食品，用黄豆发酵制成，含有大量益生菌。된장찌개就是以된장为底料，加入豆腐、蔬菜、蘑菇、辣椒等食材炖煮的汤。

된장찌개没有固定配方，每家的味道都不一样——这正是它的魅力。韩国人对된장찌개有极深的情感认同，离家在外的人最想念的往往是“엄마가 끓여준 된장찌개”（妈妈煮的된장찌개）。这碗汤的味道，就是家的味道。`,
