      desc: '《顶楼》펜트하우스\n\n财阀剧里的豪华饭局，桌上摆满了小碟子——这就是한정식（韩国定食）。한정식是韩国最正式的传统套餐，从古代宫廷料理演变而来，一桌可以有十几道到几十道菜，一道一道端上来，展示食材的多样和厨师的功夫。\n\n한정식餐厅通常是韩屋（传统建筑）改造的，服务员穿韩服，菜品从小菜、汤、腌制品、蒸菜、炒菜到甜点依次呈现。价格从5万韩元到20万韩元一位不等，是韩国人接待重要客人、庆祝重要纪念日的选择。',
